const fs = require('fs');

const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
let index = 0;

const M = data[index++];
const N = data[index++];

const stock = [];
for (let i = 0; i < M; i++) {
  stock.push(data.slice(index, index + N));
  index += N;
}

const P = data[index++];
let sold = 0;

for (let k = 0; k < P; k++) {
  const type = data[index++] - 1;
  const size = data[index++] - 1;

  if (stock[type][size] > 0) {
    stock[type][size]--;
    sold++;
  }
}

console.log(sold);
